//! The shared `dti/1` vector (`forge-contracts/fixtures/org/dti-2of3.json`), generated by
//! dash-threshold-identity itself.

use serde_json::Value;

use super::canon::canonical;
use super::derive::{MemberKeys, Seed};
use super::request::{self, RequestStatus};
use super::state::{reduce, ProposalStatus, RoomState};
use super::{bls, envelope, member, signing_ceremonies, signing_slot};

fn vector() -> Value {
    serde_json::from_str(include_str!(
        "../../../../forge-contracts/fixtures/org/dti-2of3.json"
    ))
    .unwrap()
}

fn seed(v: &Value, i: usize) -> Seed {
    let m = &v["members"][i];
    Seed::from_phrase(
        m["mnemonic"].as_str().unwrap(),
        m["passphrase"].as_str().unwrap(),
    )
    .unwrap()
}

fn room(v: &Value, extra: &[&Value]) -> RoomState {
    let mut msgs: Vec<Value> = v["ceremonyMessages"].as_array().unwrap().clone();
    msgs.extend(extra.iter().map(|e| (*e).clone()));
    reduce(&msgs, v["room"].as_str())
}

fn cid(v: &Value) -> &str {
    v["cid"].as_str().unwrap()
}

#[test]
fn canonical_json_matches_dti() {
    let v = vector();
    for case in v["canonical"].as_array().unwrap() {
        assert_eq!(canonical(&case[0]).unwrap(), case[1].as_str().unwrap());
    }
}

#[test]
fn envelope_ids_and_signatures_match() {
    let v = vector();
    let msgs = v["ceremonyMessages"].as_array().unwrap();
    for (i, id) in v["expected"]["envelopeIds"]
        .as_array()
        .unwrap()
        .iter()
        .enumerate()
    {
        assert_eq!(envelope::id(&msgs[i]).unwrap(), id.as_str().unwrap());
    }
    for m in msgs {
        assert!(envelope::verify(m));
    }
    assert_eq!(
        envelope::id(&v["proposals"]["one"]["envelope"]).unwrap(),
        v["proposals"]["one"]["id"].as_str().unwrap()
    );
    for e in [&v["reject"], &v["broadcast"], &v["approvals"]["m1"]] {
        assert!(envelope::verify(e));
    }
}

#[test]
fn a_tampered_envelope_is_rejected() {
    let v = vector();
    let mut m = v["approvals"]["m1"].clone();
    m["body"]["shares"]["x"] = Value::from(1);
    assert!(!envelope::verify(&m));
    let mut m = v["ceremonyMessages"][0].clone();
    m["at"] = Value::from("2026-11-24T19:30:31.506Z");
    assert!(!envelope::verify(&m));
    let state = reduce(&[m], v["room"].as_str());
    assert!(state.hellos.is_empty());
}

#[test]
fn member_keys_derive_from_the_phrase() {
    let v = vector();
    for i in 0..3 {
        let keys = MemberKeys::derive(&seed(&v, i));
        let m = &v["members"][i];
        assert_eq!(keys.auth_pub, m["authPub"].as_str().unwrap());
        assert_eq!(keys.transport_pub, m["transportPub"].as_str().unwrap());
        assert_eq!(keys.fingerprint, m["fingerprint"].as_str().unwrap());
    }
}

#[test]
fn the_ceremony_completes_with_the_vector_keys() {
    let v = vector();
    let state = room(&v, &[]);
    let c = &state.ceremonies[cid(&v)];
    let result = c.result.as_ref().expect("complete");
    assert_eq!(result.transcript, v["transcript"].as_str().unwrap());
    for (slot, want) in v["keys"].as_object().unwrap() {
        let (k, keys) = &result.keys[slot];
        assert_eq!(
            keys.group_public_key,
            want["groupPublicKey"].as_str().unwrap()
        );
        assert_eq!(i64::from(k.key_id), want["keyId"].as_i64().unwrap());
        for (i, pk) in want["publicShares"].as_object().unwrap() {
            assert_eq!(
                &keys.public_shares[&i.parse::<u32>().unwrap()],
                pk.as_str().unwrap()
            );
        }
    }
    let (slot, _) = signing_slot(c).unwrap();
    assert_eq!((slot.slot.as_str(), slot.key_id), ("high", 2));
    assert_eq!(signing_ceremonies(&state).len(), 1);
}

#[test]
fn a_ceremony_missing_a_completion_is_not_complete() {
    let v = vector();
    let msgs: Vec<Value> = v["ceremonyMessages"].as_array().unwrap()[..15].to_vec();
    let state = reduce(&msgs, v["room"].as_str());
    assert!(!state.ceremonies[cid(&v)].is_complete());
}

#[test]
fn each_member_recovers_the_share_matching_its_public_share() {
    let v = vector();
    let state = room(&v, &[]);
    for i in 0..3 {
        let s = seed(&v, i);
        let keys = MemberKeys::derive(&s);
        let shares = member::recover_shares(&s, &keys, &state, cid(&v)).unwrap();
        assert_eq!(
            i64::from(shares.index),
            v["members"][i]["index"].as_i64().unwrap()
        );
        for (slot, pk) in v["members"][i]["publicShares"].as_object().unwrap() {
            let share = shares.get(slot).unwrap();
            assert_eq!(bls::g1_hex(&bls::g1(share)), pk.as_str().unwrap());
        }
    }
}

#[test]
fn a_wrong_phrase_recovers_no_share() {
    let v = vector();
    let state = room(&v, &[]);
    let other = Seed::from_bytes([7; 64]);
    let keys = MemberKeys::derive(&other);
    assert!(member::recover_shares(&other, &keys, &state, cid(&v)).is_err());
}

#[test]
fn approvals_are_reproduced_byte_for_byte() {
    let v = vector();
    let state = room(
        &v,
        &[
            &v["proposals"]["one"]["envelope"],
            &v["proposals"]["two"]["envelope"],
        ],
    );
    for (name, i, proposal) in [("m1", 0, "one"), ("m3", 2, "one"), ("m2OnTwo", 1, "two")] {
        let want = &v["approvals"][name];
        let s = seed(&v, i);
        let keys = MemberKeys::derive(&s);
        let pid = v["proposals"][proposal]["id"].as_str().unwrap();
        let got = member::approve(&s, &keys, &state, pid, want["at"].as_str().unwrap()).unwrap();
        assert_eq!(&got, want, "{name}");
    }
}

#[test]
fn proposal_states_match_the_vector() {
    let v = vector();
    let one = &v["proposals"]["one"]["envelope"];
    let pid = v["proposals"]["one"]["id"].as_str().unwrap();
    let exp = &v["expected"];

    let state = room(&v, &[one, &v["approvals"]["m1"]]);
    let p = &state.proposals[pid];
    assert_eq!(p.status, ProposalStatus::Collecting);
    assert_eq!(
        serde_json::to_value(p.status).unwrap(),
        exp["afterOneApproval"]["status"]
    );
    let shares: Vec<u32> = p.requirements[0].shares.keys().copied().collect();
    assert_eq!(
        serde_json::to_value(shares).unwrap(),
        exp["afterOneApproval"]["shares"]
    );

    let state = room(&v, &[one, &v["approvals"]["m1"], &v["approvals"]["m3"]]);
    let p = &state.proposals[pid];
    assert_eq!(
        serde_json::to_value(p.status).unwrap(),
        exp["afterTwo"]["status"]
    );
    let shares: Vec<u32> = p.requirements[0].shares.keys().copied().collect();
    assert_eq!(
        serde_json::to_value(shares).unwrap(),
        exp["afterTwo"]["shares"]
    );
    let combined = member::combine(&state, pid).unwrap();
    let c = combined.values().next().unwrap();
    assert_eq!(hex::encode(c.signature), exp["combined"].as_str().unwrap());
    assert_eq!(c.signers, vec![1, 3]);

    let state = room(
        &v,
        &[
            one,
            &v["approvals"]["m1"],
            &v["approvals"]["m3"],
            &v["broadcast"],
        ],
    );
    assert_eq!(
        serde_json::to_value(state.proposals[pid].status).unwrap(),
        exp["afterBroadcast"]
    );

    let two = &v["proposals"]["two"];
    let tid = two["id"].as_str().unwrap();
    let state = room(
        &v,
        &[&two["envelope"], &v["approvals"]["m2OnTwo"], &v["reject"]],
    );
    let p = &state.proposals[tid];
    assert_eq!(
        serde_json::to_value(p.status).unwrap(),
        exp["two"]["status"]
    );
    let rejections: Vec<&String> = p.rejections.keys().collect();
    assert_eq!(
        serde_json::to_value(rejections).unwrap(),
        exp["two"]["rejections"]
    );
}

#[test]
fn one_share_cannot_make_a_valid_signature() {
    let v = vector();
    let one = &v["proposals"]["one"];
    let pid = one["id"].as_str().unwrap();
    let state = room(&v, &[&one["envelope"], &v["approvals"]["m1"]]);
    assert!(member::combine(&state, pid).is_err());
    let share = v["approvals"]["m1"]["body"]["shares"]
        .as_object()
        .unwrap()
        .values()
        .next()
        .unwrap();
    let sig = hex::decode(share["share"].as_str().unwrap()).unwrap();
    let alone = bls::combine(&[(1, sig)]).unwrap();
    let message = hex::decode(one["signable"].as_str().unwrap()).unwrap();
    let group = v["keys"]["high"]["groupPublicKey"].as_str().unwrap();
    assert!(!bls::verify(&alone, &message, group));
}

#[test]
fn a_tampered_share_is_rejected() {
    let v = vector();
    let one = &v["proposals"]["one"];
    let pid = one["id"].as_str().unwrap();
    let s = seed(&v, 2);
    let keys = MemberKeys::derive(&s);
    let state = room(&v, &[&one["envelope"], &v["approvals"]["m1"]]);
    let key = format!("{}/high", cid(&v));
    let forged_share = hex::encode(bls::sign_share(&blstrs_plus::Scalar::from(5u64), b"x"));
    let forged = envelope::seal(
        &keys,
        v["room"].as_str().unwrap(),
        "approve",
        serde_json::json!({ "proposalId": pid, "shares": { key: { "index": 3, "share": forged_share } } }),
        "2026-11-24T19:30:33.000Z",
    )
    .unwrap();
    let state2 = room(&v, &[&one["envelope"], &v["approvals"]["m1"], &forged]);
    let p = &state2.proposals[pid];
    assert_eq!(p.status, ProposalStatus::Collecting);
    assert_eq!(p.requirements[0].invalid_shares, vec![3]);
    assert_eq!(state.proposals[pid].status, ProposalStatus::Collecting);
}

#[test]
fn requests_group_by_forge_note() {
    let v = vector();
    let state = room(
        &v,
        &[
            &v["proposals"]["one"]["envelope"],
            &v["approvals"]["m1"],
            &v["approvals"]["m3"],
        ],
    );
    let members = state.ceremonies[cid(&v)]
        .config
        .participants
        .iter()
        .map(|p| p.auth_pub.clone())
        .collect();
    let reqs = request::requests(&state, cid(&v), &members);
    assert_eq!(reqs.len(), 1);
    assert!(
        !reqs[0].forge,
        "the vector's note group is not 16 hex digits"
    );
    assert_eq!(
        request::status(&state, &reqs[0], None),
        RequestStatus::Ready
    );
    assert_eq!(request::collected(&state, &reqs[0]), (2, 2));
    let p2 = v["members"][1]["authPub"].as_str().unwrap();
    assert!(!request::waits_for(&state, &reqs[0], p2));

    let note = request::Note {
        group: "0011223344556677".into(),
        seq: 0,
        of: 1,
        title: "t".into(),
    };
    assert_eq!(request::Note::parse(&note.to_json()), Some(note));
    assert_eq!(
        request::Note::parse("{\"forge\":1,\"group\":\"g1\",\"seq\":0,\"of\":1,\"title\":\"x\"}"),
        None
    );
}

#[test]
fn a_request_reads_declined_once_the_rest_cannot_reach_the_threshold() {
    let v = vector();
    let one = &v["proposals"]["one"]["envelope"];
    let pid = v["proposals"]["one"]["id"].as_str().unwrap();
    let room_id = v["room"].as_str().unwrap();
    let at = "2030-01-01T00:00:00.000Z";
    let no = |i: usize| {
        member::reject(&MemberKeys::derive(&seed(&v, i)), room_id, pid, "no", at).unwrap()
    };
    let (no1, no2, no3) = (no(0), no(1), no(2));
    let outsider = Seed::from_phrase(
        "abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about",
        "",
    )
    .unwrap();
    let no_outsider =
        member::reject(&MemberKeys::derive(&outsider), room_id, pid, "no", at).unwrap();
    let declined = |extra: &[&Value]| {
        let mut msgs = vec![one];
        msgs.extend_from_slice(extra);
        let state = room(&v, &msgs);
        let members = state.ceremonies[cid(&v)]
            .config
            .participants
            .iter()
            .map(|p| p.auth_pub.clone())
            .collect();
        let req = request::requests(&state, cid(&v), &members).remove(0);
        request::declined_out(&state, &req, &state.ceremonies[cid(&v)])
    };
    assert!(!declined(&[&no2]), "one decline of 2 of 3 leaves two");
    assert!(declined(&[&no2, &no3]));
    assert!(
        !declined(&[&no2, &no_outsider]),
        "a non-member's decline is not counted"
    );
    assert!(
        !declined(&[&v["approvals"]["m1"], &no1, &no2]),
        "a member who also approved is not counted"
    );
    assert!(declined(&[&v["approvals"]["m1"], &no2, &no3]));
    assert!(
        !declined(&[&v["approvals"]["m1"], &v["approvals"]["m3"], &no2]),
        "ready"
    );
}
